@@ -271,0 +282,25 @@
+
+abstract value class Vehicle {
+    String make;
+    Vehicle(String m) {
+        make = m;
+    }
+}
+
+value class Car extends Vehicle {
+    int numWheels;
+    Car(String m, int w) {
+        numWheels = w;
+        super(m);
+    }
+}
+
+value class CarPair {
+    @NullRestricted Car car1;
+    @NullRestricted Car car2;
+
+    CarPair(String m1, int w1, String m2, int w2) {
+        car1 = new Car(m1, w1);
+        car2 = new Car(m2, w2);
+    }
+}
